({ tick, justPressed, random, state }) => {
  const commands = [];
  if (state === null) {
    // A blank label with the built-in id hides the score, which the title has no use for.
    commands.push({ kind: "hud", id: "score", text: " ", x: 0, y: 0 });
    commands.push({ kind: "hud", id: "logo", text: "Kindle", x: 640, y: 120, size: 170, color: "#ffe2a8", align: "center", fontId: "title" });
    commands.push({ kind: "hud", id: "sub", text: "relight the drowned temple", x: 640, y: 330, size: 34, color: "#9fe8d8", align: "center", fontId: "title" });
  }
  if (tick % 45 === 0) {
    const on = Math.floor(tick / 45) % 2 === 0;
    commands.push({ kind: "hud", id: "start", text: on ? "PRESS SPACE" : "", x: 640, y: 600, size: 36, color: "#ffcf7a", align: "center", fontId: "hud" });
  }
  if (tick % 5 === 0) {
    commands.push({ kind: "spawn", prefabId: "trail", x: -3.2 + (random() - 0.5) * 0.6, y: -0.6, velocityX: (random() - 0.5) * 0.5, velocityY: 1.6 + random() });
  }
  if (justPressed.includes("space")) commands.push({ kind: "sceneTransition", sceneId: "temple" });
  return { state: 1, commands };
}

({ events, entity, world, state, random }) => {
  const s = state ?? { x: entity.x, y: entity.y, lead: 0, lastX: entity.x, shake: 0 };
  for (const event of events) {
    if (event.kind !== "trigger") continue;
    if (event.event === "hurt") s.shake = Math.max(s.shake, 0.5);
    if (event.event === "stomp") s.shake = Math.max(s.shake, 0.22);
    if (event.event === "victory") s.shake = Math.max(s.shake, 0.4);
  }
  const hero = world.find((item) => item.source === "hero");
  if (hero) {
    const dx = hero.x - s.lastX;
    s.lastX = hero.x;
    if (Math.abs(dx) > 0.02) s.lead += ((dx > 0 ? 2.4 : -2.4) - s.lead) * 0.04;
    s.x += (hero.x + s.lead - s.x) * 0.12;
    const targetY = hero.y + 2.2;
    if (Math.abs(targetY - s.y) > 0.6) s.y += (targetY - s.y) * 0.08;
  }
  s.x = Math.max(7, Math.min(228, s.x));
  s.y = Math.max(1.8, s.y);
  const x = s.x + (random() * 2 - 1) * s.shake;
  const y = s.y + (random() * 2 - 1) * s.shake;
  s.shake *= 0.85;
  if (s.shake < 0.01) s.shake = 0;
  return { state: s, commands: [{ kind: "setPosition", x, y }] };
}

({ tick, pressed, justPressed, events, entity, world, state, random }) => {
  const s = state ?? { vx: 0, facing: 1, coyote: 0, buffer: 0, rising: false, lock: 0, dead: 0, hurtFlash: 0,
    spawn: { x: entity.x, y: entity.y }, lit: [], embers: 0, deaths: 0, grounded: true, fall: 0,
    won: -1, anim: "", hud: "", note: "", noteUntil: 0, start: tick };
  const commands = [];
  const me = entity.id;
  const find = (id) => world.find((item) => item.id === id);
  const burst = (prefabId, x, y, count, speed, up = 0) => {
    for (let i = 0; i < count; i += 1) {
      const a = random() * Math.PI * 2;
      const v = speed * (0.35 + random() * 0.65);
      commands.push({ kind: "spawn", prefabId, x, y, velocityX: Math.cos(a) * v, velocityY: Math.sin(a) * v + up });
    }
  };
  const note = (text, ticks) => { s.note = text; s.noteUntil = tick + ticks; };
  let vy = entity.velocityY;
  const die = () => {
    if (s.dead > 0 || s.won >= 0) return;
    s.dead = 45;
    s.deaths += 1;
    burst("spark", entity.x, entity.y, 14, 7);
    commands.push({ kind: "emit", event: "hurt" });
  };

  const handled = new Set();
  for (const event of events) {
    if (event.kind === "collected" && event.byId === me) {
      s.embers += 1;
      burst("spark", entity.x, entity.y + 0.2, 5, 3.5, 1.5);
    }
    if (event.kind !== "contact" || event.phase === "exit") continue;
    const other = event.entityId === me ? event.otherId : event.otherId === me ? event.entityId : "";
    if (!other || handled.has(other)) continue;
    handled.add(other);
    const target = find(other);
    if (other.startsWith("crawler") && target && s.dead === 0) {
      if (entity.velocityY < 0.5 && entity.y - target.y > 0.3) {
        commands.push({ kind: "despawn", entityId: other });
        commands.push({ kind: "emit", event: "stomp" });
        burst("spark", target.x, target.y, 10, 5);
        burst("dust", target.x, target.y - 0.2, 4, 1.5);
        vy = pressed.includes("space") || pressed.includes("up") ? 17 : 11;
        s.rising = true;
      } else {
        die();
      }
    } else if (other.startsWith("thorns")) {
      die();
    } else if (other.startsWith("brazier") && target && !s.lit.includes(other)) {
      s.lit.push(other);
      s.spawn = { x: target.x, y: target.y - 0.3 };
      commands.push({ kind: "spawn", prefabId: "brazierFlame", x: target.x, y: target.y + 0.95 });
      commands.push({ kind: "emit", event: "checkpoint" });
      burst("spark", target.x, target.y + 0.9, 12, 5, 2);
      if (s.lit.length > 1) note("brazier rekindled", 150);
    } else if (other.startsWith("mushroom") && target && entity.velocityY <= 0.5 && entity.y > target.y + 0.1) {
      vy = 26;
      s.rising = false;
      commands.push({ kind: "emit", event: "bounce" });
      burst("wisp", target.x, target.y + 0.5, 8, 4, 1);
    } else if (other === "beacon" && target && s.won < 0) {
      s.won = tick;
      commands.push({ kind: "spawn", prefabId: "beaconFlame", x: target.x, y: target.y + 2.05 });
      commands.push({ kind: "emit", event: "victory" });
      burst("spark", target.x, target.y + 2, 30, 9, 2);
    }
  }

  // A defeated hero waits as a cloud of sparks, then reappears at the last brazier.
  if (s.dead > 0) {
    s.dead -= 1;
    if (s.dead === 0) {
      commands.push({ kind: "setPosition", x: s.spawn.x, y: s.spawn.y });
      s.vx = 0;
      s.hurtFlash = 40;
      burst("spark", s.spawn.x, s.spawn.y, 10, 4, 1);
      commands.push({ kind: "setVelocity", x: 0, y: 0 });
    } else {
      commands.push({ kind: "setVelocity", x: 0, y: 0 });
    }
    commands.push({ kind: "setVisual", opacity: 0 });
  } else {
    const grounded = entity.touching.down;
    const wall = s.won >= 0 ? 0 : entity.touching.left ? -1 : entity.touching.right ? 1 : 0;
    const jumpPressed = justPressed.includes("space") || justPressed.includes("up");
    const jumpHeld = pressed.includes("space") || pressed.includes("up");
    let axis = s.won >= 0 ? 0 : (pressed.includes("right") ? 1 : 0) - (pressed.includes("left") ? 1 : 0);
    s.coyote = grounded ? 7 : Math.max(0, s.coyote - 1);
    s.buffer = jumpPressed && s.won < 0 ? 8 : Math.max(0, s.buffer - 1);
    if (s.lock > 0) { s.lock -= 1; axis = 0; }
    const target = axis * 8.5;
    const blend = s.lock > 0 ? 0 : grounded ? (axis === 0 ? 0.3 : 0.22) : 0.12;
    s.vx += (target - s.vx) * blend;
    if (wall !== 0 && Math.sign(s.vx) === wall) s.vx = 0;
    const sliding = !grounded && wall !== 0 && axis === wall && vy < 0;
    if (sliding) {
      vy = Math.max(vy, -3.2);
      if (tick % 6 === 0) commands.push({ kind: "spawn", prefabId: "dust", x: entity.x + wall * 0.35, y: entity.y + 0.2, velocityX: -wall * 0.4, velocityY: 0.6 });
    }
    if (s.buffer > 0 && s.coyote > 0) {
      vy = 17.5;
      s.buffer = 0;
      s.coyote = 0;
      s.rising = true;
      commands.push({ kind: "emit", event: "jump" });
      burst("dust", entity.x, entity.y - 0.4, 4, 1.4);
    } else if (s.buffer > 0 && wall !== 0 && !grounded) {
      vy = 16;
      s.vx = -wall * 9;
      s.facing = -wall;
      s.lock = 9;
      s.buffer = 0;
      s.rising = true;
      commands.push({ kind: "emit", event: "jump" });
      burst("dust", entity.x + wall * 0.35, entity.y, 4, 1.4);
    }
    // Letting go of jump early cuts the rise, so tap and hold give different heights.
    if (s.rising && !jumpHeld && vy > 4) { vy *= 0.45; s.rising = false; }
    if (vy <= 0) s.rising = false;
    vy = Math.max(vy, -21);
    if (grounded && !s.grounded && s.fall < -9) {
      burst("dust", entity.x, entity.y - 0.4, 5, 1.8);
      commands.push({ kind: "emit", event: "land" });
    }
    s.grounded = grounded;
    s.fall = entity.velocityY;
    if (entity.y < -9) die();
    if (axis !== 0 && s.lock === 0) s.facing = axis;
    commands.push({ kind: "setVelocity", x: s.vx, y: vy });

    const anim = sliding ? "slide" : !grounded ? (vy > 0 ? "jump" : "fall") : Math.abs(s.vx) > 1.2 ? "run" : "idle";
    if (anim !== s.anim) { s.anim = anim; commands.push({ kind: "playAnimation", clip: anim }); }
    if (s.hurtFlash > 0) s.hurtFlash -= 1;
    const blink = s.hurtFlash > 0 && Math.floor(s.hurtFlash / 4) % 2 === 0;
    commands.push({ kind: "setVisual", flipX: (sliding ? wall : s.facing) < 0, opacity: blink ? 0.35 : 1 });
    if (tick % 3 === 0) {
      commands.push({ kind: "spawn", prefabId: "trail", x: entity.x - s.facing * 0.2 + (random() - 0.5) * 0.2, y: entity.y + 0.35,
        velocityX: -s.vx * 0.12 + (random() - 0.5) * 0.4, velocityY: 0.9 + random() * 0.6 });
    }
  }

  // Lit braziers near the hero shed rising sparks.
  if (tick % 8 === 0) {
    for (const id of s.lit) {
      const lit = find(id);
      if (lit && Math.abs(lit.x - entity.x) < 14) {
        commands.push({ kind: "spawn", prefabId: "trail", x: lit.x + (random() - 0.5) * 0.5, y: lit.y + 1.2, velocityX: (random() - 0.5) * 0.6, velocityY: 1.4 + random() });
      }
    }
  }

  const hud = (id, text, x, y, size, color, align, fontId = "hud") => commands.push({ kind: "hud", id, text, x, y, size, color, align, fontId });
  const seconds = Math.floor(((s.won >= 0 ? s.won : tick) - s.start) / 60);
  const clock = `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
  const summary = `${s.embers}|${s.lit.length}|${s.deaths}|${clock}`;
  if (summary !== s.hud) {
    s.hud = summary;
    hud("score", `EMBERS  ${s.embers} / 73`, 40, 26, 40, "#ffcf7a", "left");
    hud("braziers", `BRAZIERS  ${s.lit.length} / 4`, 40, 70, 28, "#9fe8d8", "left");
    hud("clock", clock, 1240, 26, 40, "#f4ead8", "right");
    hud("deaths", s.deaths > 0 ? `FALLEN  ${s.deaths}` : "", 1240, 70, 28, "#c89a8a", "right");
  }
  const noteText = tick < s.noteUntil ? s.note : "";
  if (noteText !== (s.shown ?? "")) {
    s.shown = noteText;
    hud("note", noteText, 640, 150, 44, "#ffe2a8", "center", "title");
  }
  if (tick - s.start === 30) note("arrows to run  ·  space to jump  ·  jump off walls", 330);
  if (s.won >= 0) {
    const since = tick - s.won;
    if (since === 60) {
      hud("win", "the temple burns again", 640, 200, 82, "#ffe7b0", "center", "title");
      hud("stats", `${s.embers} of 73 embers  ·  ${clock}  ·  fallen ${s.deaths}`, 640, 318, 34, "#f4ead8", "center");
    }
    if (since >= 150 && since % 50 === 0) hud("again", Math.floor(since / 50) % 2 === 0 ? "press space to play again" : "", 640, 380, 28, "#ffcf7a", "center");
    if (since >= 150 && justPressed.includes("space")) commands.push({ kind: "sceneTransition", sceneId: "title" });
  }
  return { state: s, commands };
}
